SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND recalled_at IS NULL
  AND seq > #{afterSeq} AND seq < #{beforeSeq}
  AND msg_type IN

      #{type}

  AND sender_id = #{filter.senderId}
  AND created_at >= #{from}
  AND created_at < #{to}

      AND ( LIKE '%https://%'
          OR  LIKE '%http://%')


      AND (msg_type IN (2, 3, 4, 5) OR  LIKE #{filter.pattern} ESCAPE '!')

ORDER BY seq DESC
LIMIT #{limit}

SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND seq > #{afterSeq}
ORDER BY seq ASC
LIMIT #{limit}

SELECT COALESCE(MAX(seq), 0)
FROM im_message
WHERE conversation_id = #{conversationId}

SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND recalled_at IS NULL
  AND msg_type IN (1, 6)
  AND seq < #{beforeSeq}
  AND seq > #{afterSeq}
  AND content LIKE #{pattern} ESCAPE '!'
ORDER BY seq DESC
LIMIT #{limit}

SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND recalled_at IS NULL
  AND msg_type IN (2, 3, 4, 5)
  AND seq > #{afterSeq}
ORDER BY seq DESC
LIMIT #{limit}

SELECT m.id, m.conversation_id, m.sender_id, m.client_msg_id, m.seq, m.msg_type, m.content, m.created_at, m.recalled_at, m.recalled_by, m.reply_to_id, m.reply_sender_id, m.reply_preview FROM im_message m INNER JOIN im_conversation_member cm ON cm.conversation_id = m.conversation_id AND cm.user_id = #{userId} WHERE m.recalled_at IS NULL AND m.msg_type IN (2, 3, 4, 5) AND m.seq > cm.cleared_seq
AND (m.created_at < #{beforeTime} OR (m.created_at = #{beforeTime} AND m.id < #{beforeId}))
ORDER BY m.created_at DESC, m.id DESC LIMIT #{limit}
